local B64={}
do
local B="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
for i=1,64 do B64[B:byte(i)]=i-1 end
B64[61]=0
end
local function b64buffer(s)
local buf=buffer.create(#s//4*3)
local o=0
for i=1,#s,4 do
local a1,a2,a3,a4=s:byte(i,i+3)
local v=B64[a1]*262144+B64[a2]*4096+B64[a3]*64+B64[a4]
buffer.writeu8(buf,o,v//65536)
buffer.writeu8(buf,o+1,(v//256)%256)
buffer.writeu8(buf,o+2,v%256)
o=o+3
end
return buf
end
local function u16(b,o) return buffer.readu8(b,o)*256+buffer.readu8(b,o+1) end
local function s16(b,o) local x=u16(b,o) if x>=32768 then x=x-65536 end return x end
local function s8(b,o) local x=buffer.readu8(b,o) if x>=128 then x=x-256 end return x end
local function texture()
if G.tex then return G.tex end
local B="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local lut={}
for i=1,64 do lut[B:sub(i,i)]=i-1 end
local pal={}
for i=0,#_M.TEX_PALETTE/6-1 do
local h=_M.TEX_PALETTE:sub(i*6+1,i*6+6)
pal[i]={tonumber(h:sub(1,2),16),tonumber(h:sub(3,4),16),tonumber(h:sub(5,6),16)}
end
local buf=buffer.create(_M.TEX_N*_M.TEX_N*4)
local p=0
for i=1,#_M.TEX_RLE,3 do
local c=pal[lut[_M.TEX_RLE:sub(i,i)]]
local len=lut[_M.TEX_RLE:sub(i+1,i+1)]*64+lut[_M.TEX_RLE:sub(i+2,i+2)]+1
for _=1,len do
buffer.writeu8(buf,p,c[1])
buffer.writeu8(buf,p+1,c[2])
buffer.writeu8(buf,p+2,c[3])
buffer.writeu8(buf,p+3,255)
p=p+4
end
end
local img=AS:CreateEditableImage({Size=Vector2.new(_M.TEX_N,_M.TEX_N)})
img:WritePixelsBuffer(Vector2.zero,Vector2.new(_M.TEX_N,_M.TEX_N),buf)
G.tex=Content.fromObject(img)
return G.tex
end
local function mesh(p,S,tex)
local buf=b64buffer(p.d)
local o=0
local em=AS:CreateEditableMesh()
local nv=u16(buf,o) o=o+2
local vid={}
for i=1,nv do
vid[i]=em:AddVertex(Vector3.new(s16(buf,o)/20000*S,s16(buf,o+2)/20000*S,s16(buf,o+4)/20000*S))
o=o+6
end
local nuv=u16(buf,o) o=o+2
local uid={}
for i=1,nuv do
local u,v=u16(buf,o)/65535,u16(buf,o+2)/65535
v=1-v
uid[i]=em:AddUV(Vector2.new(u,v))
o=o+4
end
local nn=u16(buf,o) o=o+2
local nid={}
for i=1,nn do
local nvec=Vector3.new(s8(buf,o)/127,s8(buf,o+1)/127,s8(buf,o+2)/127).Unit
nid[i]=em:AddNormal(nvec)
o=o+3
end
local nt=u16(buf,o) o=o+2
for _=1,nt do
local va,ua,na=u16(buf,o)+1,u16(buf,o+2)+1,u16(buf,o+4)+1
local vb,ub,nb=u16(buf,o+6)+1,u16(buf,o+8)+1,u16(buf,o+10)+1
local vc,uc,nc=u16(buf,o+12)+1,u16(buf,o+14)+1,u16(buf,o+16)+1
o=o+18
local f=em:AddTriangle(vid[va],vid[vb],vid[vc])
em:SetFaceUVs(f,{uid[ua],uid[ub],uid[uc]})
em:SetFaceNormals(f,{nid[na],nid[nb],nid[nc]})
end
local mp=AS:CreateMeshPartAsync(Content.fromObject(em))
pcall(function() mp.DoubleSided=true end)
pcall(function() mp.TextureContent=tex end)
return mp
end
local function sample(a,k,out,pp)
local base=k*(#ROT*4+6)
for j=1,#ROT do
local v=bit32.byteswap(buffer.readu32(a.buf,base+(j-1)*4))
local idx=bit32.rshift(v,30)
local c1=(bit32.extract(v,20,10)/1023*2-1)*0.70711
local c2=(bit32.extract(v,10,10)/1023*2-1)*0.70711
local c3=(bit32.extract(v,0,10)/1023*2-1)*0.70711
local big=math.sqrt(math.max(0,1-(c1*c1+c2*c2+c3*c3)))
local x,y,z,w
if idx==0 then x,y,z,w=big,c1,c2,c3
elseif idx==1 then x,y,z,w=c1,big,c2,c3
elseif idx==2 then x,y,z,w=c1,c2,big,c3
else x,y,z,w=c1,c2,c3,big end
out[j]=CFrame.new(0,0,0,x,y,z,w)
end
local pb=base+#ROT*4
pp.X=s16(a.buf,pb)/5000
pp.Y=s16(a.buf,pb+2)/5000
pp.Z=s16(a.buf,pb+4)/5000
end
local decoded={}
local function getAnim(hex)
if decoded[hex] then return decoded[hex] end
local s=_M.ANIM_DATA[hex]
if not s then return nil end
local a={n=s.n,step=s.step,keys=s.keys,buf=b64buffer(s.d)}
decoded[hex]=a
return a
end
