local okT,eT=pcall(texture)
if okT then tex=eT else say("texture failed (enable Mesh/Image APIs): "..tostring(eT),true) end
local model=Instance.new("Model")
model.Name="Mario64"
model.Parent=ch
local byBone={}
for _,p in ipairs(_M.MESH_PARTS) do byBone[p.bone]=p end
local piece,center={},{}
local failed=false
for _,name in ipairs(ROT) do
local p=byBone[name]
local part
if p then
local ok,res=pcall(mesh,p,S,tex)
if ok then part=res
else
if not failed then failed=true say("mesh failed, using blocks: "..tostring(res),true) end
part=Instance.new("Part")
part.Size=p.size*S
part.Material=Enum.Material.SmoothPlastic
local key=name:match("Head") or name:match("Hand") or name:match("Shoe") or name:match("Forearm") or name:match("Arm") or name:match("Thigh") or name:match("Leg") or name
part.Color=COL[key] or Color3.new(1,1,1)
end
center[name]=p.c*S
else
part=Instance.new("Part")
part.Size=Vector3.new(0.2,0.2,0.2)
part.Transparency=1
center[name]=Vector3.zero
end
part.Name="M64_"..name
part.Anchored=false
part.CanCollide=false
part.CanQuery=false
part.CanTouch=false
part.Massless=true
part.Parent=model
piece[name]=part
end
local feet=root.Size.Y/2+hum.HipHeight
local bodyC0=CFrame.new(0,-feet+0.114*S-LOWER*MH/5,0)*CFrame.Angles(0,FACE,0)
local motors,baseC0,nodeT={},{},{}
for j,name in ipairs(ROT) do
local m=Instance.new("Motor6D")
m.Name="M64_"..name
if name=="Body" then
m.Part0=root
m.C0=bodyC0
m.C1=CFrame.new(-center[name])
else
local par=PARENT[name]
m.Part0=piece[par]
m.C0=CFrame.new(-center[par])
m.C1=CFrame.new(-center[name])
end
m.Part1=piece[name]
m.Parent=piece[name]
motors[j]=m
baseC0[j]=m.C0
nodeT[j]=(_M.NODE_T[name] or Vector3.zero)*S
end
