local st={name=nil,data=nil,t=0,spd=1,tgt=1,loop=false,lo=0,hi=0}
local kA,kB={},{}
local pA,pB={X=0,Y=0,Z=0},{X=0,Y=0,Z=0}
local lastPose,lastPos=nil,Vector3.zero
local blendFrom,blendFromPos,blendT,blendDur=nil,nil,1,0.1
local function play(name,speed)
if st.name==name then st.tgt=speed return end
local hex=MAP[name]
local data=hex and getAnim(hex)
if not data then return end
if lastPose then
blendFrom=table.clone(lastPose)
blendFromPos=lastPos
blendT=0
blendDur=0.12
end
st.name=name
st.data=data
st.t=0
st.spd=speed
st.tgt=speed
st.loop=LOOPED[name]==true
local seg=SEG[name]
st.lo=seg and seg[1] or 0
st.hi=seg and seg[2] or (data.n-1)
end
local function done()
return st.data and not st.loop and st.lo+st.t*30>=st.hi-0.01
end
local function pose(dt)
local a=st.data
if not a then return end
st.spd=st.spd+(st.tgt-st.spd)*math.min(1,dt*10)
st.t=st.t+dt*st.spd
local last=a.n-1
local f
if st.loop then f=st.lo+(st.t*30)%math.max(st.hi-st.lo,1) else f=math.min(st.lo+st.t*30,st.hi) end
local k0=math.min(math.floor(f/a.step),a.keys-1)
local k1=math.min(k0+1,a.keys-1)
local t0=math.min(k0*a.step,last)
local t1=math.min(k1*a.step,last)
local al=(t1>t0) and math.clamp((f-t0)/(t1-t0),0,1) or 0
sample(a,k0,kA,pA)
sample(a,k1,kB,pB)
local ps={}
local pos=Vector3.new(pA.X+(pB.X-pA.X)*al,pA.Y+(pB.Y-pA.Y)*al,pA.Z+(pB.Z-pA.Z)*al)*S
for j=1,#ROT do ps[j]=kA[j]:Lerp(kB[j],al) end
lastPose=table.clone(ps)
lastPos=pos
if blendFrom and blendT<1 then
blendT=blendT+dt/blendDur
local w=math.clamp(blendT,0,1)
for j=1,#ROT do ps[j]=blendFrom[j]:Lerp(ps[j],w) end
pos=blendFromPos:Lerp(pos,w)
if blendT>=1 then blendFrom=nil end
end
for j=1,#ROT do
local cf
if j==1 then cf=CFrame.new(pos)*ps[j] else cf=CFrame.new(nodeT[j])*ps[j] end
motors[j].C0=baseC0[j]*cf
end
end
local dead=false
local function deathcam()
pcall(function() RS:UnbindFromRenderStep("64DudeCamA") end)
pcall(function() RS:UnbindFromRenderStep("64DudeCam") end)
if G.dc then G.dc:Disconnect() end
local cam=workspace.CurrentCamera
if not cam then return end
local focus0=root.Position
local off=cam.CFrame.Position-focus0
local dist0=math.clamp(off.Magnitude,8,40)
local dir=off.Magnitude>0.1 and off.Unit or Vector3.new(0,0.3,1).Unit
local fov0=cam.FieldOfView
G.fov0=fov0
local t0=os.clock()
cam.CameraType=Enum.CameraType.Scriptable
G.dc=RS.RenderStepped:Connect(function()
local c=workspace.CurrentCamera
if not c then return end
local t=os.clock()-t0
local k=math.clamp(t/2.2,0,1)
k=1-(1-k)*(1-k)
local dist=dist0+(math.max(8,dist0*0.6)-dist0)*k
local ramp=math.clamp(t/0.8,0,1)
local sway=Vector3.new(math.sin(t*1.9)*0.5,math.sin(t*2.7)*0.35,0)*ramp
local roll=math.sin(t*1.4)*math.rad(3.5)*ramp
local focus=(root.Parent and root.Position or focus0)+Vector3.new(0,1.5,0)
c.CameraType=Enum.CameraType.Scriptable
c.CFrame=CFrame.lookAt(focus+dir*dist+sway,focus)*CFrame.Angles(0,0,roll)
c.FieldOfView=fov0-8*k
end)
end
