jt=now
if now-lastLand<0.9 then combo=combo%3+1 else combo=1 end
sfx(root,combo==3 and "jump3" or (combo==2 and "jump2" or "jump"),0.9)
landName=nil
local m=combo==2 and 1.15 or (combo==3 and 1.4 or 1)
if m>1 then root.AssemblyLinearVelocity=Vector3.new(v.X,v.Y*m,v.Z) end
end
if prev and (prev==Enum.HumanoidStateType.Freefall or prev==Enum.HumanoidStateType.Jumping) and not air then
lastLand=now
landName="land"..combo
landT=now
if combo==3 then sfx(root,"land3",0.9) end
stepT=0
end
prev=s
local name,spd="idle",1
if air then
if combo==3 then name="triple"
elseif combo==2 then name=(now-jt<0.45) and "double_rise" or "double_fall"
else name=(now-jt<0.7) and "single_jump" or "general_fall" end
if s==Enum.HumanoidStateType.Freefall and jt==0 then name="general_fall" end
elseif s==Enum.HumanoidStateType.Swimming then name=sp>2 and "swim" or "swim_idle"
elseif sp>1 then
if sp<SPEED*0.3 then name="slow_walk" elseif sp<SPEED*0.6 then name="walking" else name="running" end
spd=math.min(math.max(sp*160/(30*MH),4)/4,8)*ANIMSPEED
landName=nil
if now-stepT>math.clamp(9/sp,0.22,0.6) then stepT=now sfx(root,"step",0.5) end
elseif landName and now-landT<0.8 then
name=landName
end
if now-lastLand>1.2 and not air then combo=0 end
play(name,spd)
pose(dt)
end)
say("Mario ready",true)
end
local function camfx()
pcall(function() RS:UnbindFromRenderStep("64DudeCamA") end)
pcall(function() RS:UnbindFromRenderStep("64DudeCam") end)
if G.cin then G.cin:Disconnect() end
local T,D
local ax,ay=0,0
G.cin=UIS.InputChanged:Connect(function(i,gp)
if gp or i.UserInputType~=Enum.UserInputType.Touch then return end
ax=ax+i.Delta.X
ay=ay+i.Delta.Y
end)
RS:BindToRenderStep("64DudeCamA",Enum.RenderPriority.Camera.Value-1,function()
local cam=workspace.CurrentCamera
if not T or not cam then return end
local cf=T
if ax~=0 or ay~=0 then
local l=cf.LookVector
local yaw=math.atan2(-l.X,-l.Z)-ax*0.0141*(SENS-1)
local pit=math.clamp(math.asin(l.Y)-ay*0.0106*(SENS-1),-1.3,1.3)
cf=CFrame.new(cf.Position)*CFrame.Angles(0,yaw,0)*CFrame.Angles(pit,0,0)
ax,ay=0,0
end
cam.CFrame=cf
end)
RS:BindToRenderStep("64DudeCam",Enum.RenderPriority.Camera.Value+1,function(dt)
local cam=workspace.CurrentCamera
if not cam then return end
local t=cam.CFrame
T=t
if not D or (D.Position-t.Position).Magnitude>30 then D=t return end
dt=math.min(dt,0.05)
local p=D.Position:Lerp(t.Position,1-math.exp(-dt*CAMPOS))
local r=D.Rotation:Lerp(t.Rotation,1-math.exp(-dt*CAMROT))
D=CFrame.new(p)*r
cam.CFrame=D
end)
end
local function shadowfx()
if G.sh then pcall(function() G.sh:Destroy() end) end
pcall(function() RS:UnbindFromRenderStep("64DudeSh") end)
local s=Instance.new("Part")
s.Name="64DudeShadow"
s.Shape=Enum.PartType.Cylinder
s.Anchored=true
s.CanCollide=false
s.CanTouch=false
s.CanQuery=false
s.CastShadow=false
s.Transparency=1
s.Parent=workspace
G.sh=s
local fade
if SHADOW_IMG then
local d=Instance.new("Decal")
d.Face=Enum.NormalId.Right
d.Texture=SHADOW_IMG
d.Parent=s
fade=function(f) d.Transparency=0.2+f*0.8 end
else
local sg=Instance.new("SurfaceGui")
sg.Face=Enum.NormalId.Right
sg.LightInfluence=0
sg.Parent=s
local cg=Instance.new("CanvasGroup")
cg.BackgroundTransparency=1
cg.Size=UDim2.fromScale(1,1)
cg.Parent=sg
for _,z in ipairs({1,0.85,0.7,0.55,0.4,0.25}) do
local f=Instance.new("Frame")
f.AnchorPoint=Vector2.new(0.5,0.5)
f.Position=UDim2.fromScale(0.5,0.5)
f.Size=UDim2.fromScale(z,z)
f.BackgroundColor3=Color3.new(0,0,0)
f.BackgroundTransparency=0.88
f.BorderSizePixel=0
f.Parent=cg
Instance.new("UICorner",f).CornerRadius=UDim.new(1,0)
end
fade=function(f) cg.GroupTransparency=f end
end
local rp=RaycastParams.new()
rp.FilterType=Enum.RaycastFilterType.Exclude
RS:BindToRenderStep("64DudeSh",Enum.RenderPriority.Camera.Value+2,function()
local ch=lp.Character
local rr=ch and ch:FindFirstChild("HumanoidRootPart")
local hum=ch and ch:FindFirstChildOfClass("Humanoid")
if not rr or not hum then fade(1) return end
rp.FilterDescendantsInstances={ch,s}
local h=workspace:Raycast(rr.Position,Vector3.new(0,-80,0),rp)
if not h then fade(1) return end
local air=math.max(0,rr.Position.Y-h.Position.Y-(hum.HipHeight+rr.Size.Y/2))
local d=MH*0.75*1*math.clamp(1-air/45,0.45,1)
local n=h.Normal
local u=math.abs(n.Y)>0.9 and Vector3.zAxis or Vector3.yAxis
local y=(u-n*u:Dot(n)).Unit
s.Size=Vector3.new(0.05,d,d)
s.CFrame=CFrame.fromMatrix(h.Position+n*0.04,n,y)
fade(math.clamp(air/70,0,0.8))
end)
end
local function hud()
local pg=lp:WaitForChild("PlayerGui")
local old=pg:FindFirstChild("64DudeHUD")
if old then old:Destroy() end
local g=Instance.new("ScreenGui")
g.Name="64DudeHUD"
g.ResetOnSpawn=false
g.IgnoreGuiInset=true
g.DisplayOrder=50
local function lb(par,txt,px,w,c,sz)
local l=Instance.new("TextLabel")
l.BackgroundTransparency=1
l.Position=UDim2.fromOffset(px,0)
l.Size=UDim2.fromOffset(w,56)
l.Text=txt
l.TextColor3=c
l.TextSize=sz
l.Font=Enum.Font.FredokaOne
l.TextStrokeTransparency=0
l.TextStrokeColor3=Color3.fromRGB(40,25,10)
l.Parent=par
return l
end
local function row(x,star,n)
local f=Instance.new("Frame")
f.BackgroundTransparency=1
f.Size=UDim2.fromOffset(180,56)
f.Position=UDim2.fromScale(x,0.12)
f.Parent=g
if star then
lb(f,"★",0,56,Color3.fromRGB(255,214,40),52)
else
local c=Instance.new("Frame")
c.Size=UDim2.fromOffset(48,48)
c.Position=UDim2.fromOffset(0,4)
c.BackgroundColor3=Color3.fromRGB(215,30,30)
c.Parent=f
Instance.new("UICorner",c).CornerRadius=UDim.new(1,0)
local m=lb(c,"M",0,48,Color3.new(1,1,1),30)
m.Size=UDim2.fromScale(1,1)
end
lb(f,"×",62,40,Color3.fromRGB(190,190,215),36)
lb(f,tostring(n),104,70,Color3.fromRGB(255,150,30),56)
end
row(0.085,false,LIVES)
row(0.72,true,STARS)
g.Parent=pg
end

